import{_ as r,C as a,c as s,o as i,a3 as t,G as n}from"./chunks/framework.Dokpd4od.js";const f=JSON.parse('{"title":"Journal entries","description":"","frontmatter":{},"headers":[],"relativePath":"master/finance/accounting-entries/journal-entries.md","filePath":"master/finance/accounting-entries/journal-entries.md","lastUpdated":1792041590000}'),l={name:"master/finance/accounting-entries/journal-entries.md"};function c(g,e,d,h,u,m){const o=a("ImagePopup");return i(),s("div",null,[e[0]||(e[0]=t('<h1 id="journal-entries" tabindex="-1">Journal entries <a class="header-anchor" href="#journal-entries" aria-label="Permalink to &quot;Journal entries&quot;">​</a></h1><p>A journal entry is the accounting record behind a document or a manual adjustment. The Journal Entries page lists all of them: invoices, bills, payments and entries you type. You use it to check what Aureus booked, and to create entries that no invoice or payment covers.</p><blockquote><p><strong>In simple words:</strong> One entry is one balanced set of debit and credit lines. This page is where you read them and write your own.</p></blockquote><p>Journal entries exist in the Accounting app only. Open <code>Accounting → Journal Entries</code>.</p><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2>',5)),n(o,{src:"/images1/finance/journal_entries_list.png",alt:"Journal Entries list showing 5 rows: INV/2026/1, INV/2026/2, PBANK/2026/3, BILL/2026/4, PBANK/2026/5 with the Total summary 2,990"}),e[1]||(e[1]=t('<h3 id="columns" tabindex="-1">Columns <a class="header-anchor" href="#columns" aria-label="Permalink to &quot;Columns&quot;">​</a></h3><ul><li><strong><em>Date:</em></strong> The accounting date.</li><li><strong><em>Number:</em></strong> The entry number, for example <code>INV/2026/1</code>.</li><li><strong><em>Partner:</em></strong> The customer or vendor.</li><li><strong><em>Reference:</em></strong> An outside reference, if any.</li><li><strong><em>Journal:</em></strong> For example <strong>Customer Invoices</strong> or <strong>Bank Transactions</strong>.</li><li><strong><em>Company:</em></strong> The company of the entry.</li><li><strong><em>Total:</em></strong> The entry amount. A bill shows a minus, for example -$34,040.00. The footer sums the amounts.</li><li><strong><em>State:</em></strong> <strong>Draft</strong>, <strong>Posted</strong> or <strong>Cancelled</strong>.</li><li><strong><em>Invoice Date</em></strong> and <strong><em>Checked</em>:</strong> Hidden by default. Turn them on from the column toggle.</li></ul><h3 id="views" tabindex="-1">Views <a class="header-anchor" href="#views" aria-label="Permalink to &quot;Views&quot;">​</a></h3><p>The tabs are saved filters: <strong>Default</strong>, <strong>Draft</strong>, <strong>Posted</strong>, <strong>Sales</strong>, <strong>Purchases</strong>, <strong>Bank</strong>, <strong>Cash</strong>, <strong>Credit</strong> and <strong>Misc</strong>. The view menu also holds <strong>Reversed</strong>.</p><h3 id="group-filter-and-export" tabindex="-1">Group, filter and export <a class="header-anchor" href="#group-filter-and-export" aria-label="Permalink to &quot;Group, filter and export&quot;">​</a></h3><ul><li><strong>Group by:</strong> <strong>Partner</strong>, <strong>Journal</strong>, <strong>State</strong>, <strong>Payment Method</strong>, <strong>Date</strong>, <strong>Invoice Date</strong> or <strong>Company</strong>.</li><li><strong>Filter:</strong> by <strong>Number</strong>, <strong>Invoice Origin</strong>, <strong>Reference</strong>, <strong>Invoice Partner Display Name</strong>, <strong>Invoice Date</strong>, <strong>Invoice Due Date</strong> and dates of creation or update.</li><li><strong>Export:</strong> Click <strong>Export</strong> to download the list.</li></ul><p>See <a href="./../../getting-started/search-filter-group.html">Search, filter and group records</a>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When you click a row for an invoice or a bill, Aureus opens the invoice or bill page. Other entries open here.</p></div><h2 id="create-a-manual-entry" tabindex="-1">Create a manual entry <a class="header-anchor" href="#create-a-manual-entry" aria-label="Permalink to &quot;Create a manual entry&quot;">​</a></h2><ol><li>Click <strong>New Journal Entries</strong> on the list.</li><li>Fill in the <strong>General</strong> section.</li><li>Add the lines in the <strong>Journal Items</strong> tab.</li><li>Click <strong>Create</strong>.</li><li>Open the entry and click <strong>Confirm</strong>.</li></ol>',10)),n(o,{src:"/images1/finance/journal_entry_form.png",alt:"New journal entry with Reference 'Office rent correction', the Miscellaneous journal, and two item rows, one Debit and one Credit of 100.00"}),e[2]||(e[2]=t('<h3 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h3><ul><li><strong><em>Reference:</em></strong> A free text label. Use it to say why you book the entry.</li><li><strong><em>Accounting Date:</em></strong> The day the entry counts. It starts as today.</li><li><strong><em>Journal:</em></strong> Required. Aureus picks your general (miscellaneous) journal. Keep it for manual entries.</li></ul><h3 id="journal-items" tabindex="-1">Journal Items <a class="header-anchor" href="#journal-items" aria-label="Permalink to &quot;Journal Items&quot;">​</a></h3><p>The tab holds a table named <strong>Items</strong>. Click <strong>Add Item</strong> to add a row. Each row has:</p><ul><li><strong><em>Account:</em></strong> Required. The account to debit or credit. See <a href="./../get-started/chart-of-accounts.html">Chart of accounts</a>.</li><li><strong><em>Partner:</em></strong> Optional. Fill it for receivable or payable accounts, so the amount shows in the partner reports.</li><li><strong><em>Label:</em></strong> A short text for the line.</li><li><strong><em>Amount (Currency):</em></strong> The amount in the line currency. A positive number is a debit. A negative number is a credit.</li><li><strong><em>Currency:</em></strong> Required. Starts with the company currency.</li><li><strong><em>Taxes:</em></strong> Optional. Pick taxes that apply to the line.</li><li><strong><em>Debit</em></strong> and <strong><em>Credit</em>:</strong> Type the amount in one of them. When you type in one, Aureus clears the other and updates <strong>Amount (Currency)</strong>.</li></ul><p>The footer of the <strong>Debit</strong> and <strong>Credit</strong> columns shows the totals. Make them equal before you confirm.</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Before you click <strong>Confirm</strong>, check that the <strong>Debit</strong> and <strong>Credit</strong> totals match.</p></div><h3 id="other-information" tabindex="-1">Other Information <a class="header-anchor" href="#other-information" aria-label="Permalink to &quot;Other Information&quot;">​</a></h3><ul><li><strong><em>Checked:</em></strong> A switch. Turn it on when someone has reviewed the entry. The journal items view has the saved filter <strong>To Check</strong> for unchecked entries.</li><li><strong><em>Company:</em></strong> Starts with your current company.</li><li><strong><em>Fiscal Position:</em></strong> Adapts taxes and accounts to the partner location. See <a href="./../taxes/fiscal-positions.html">Fiscal positions</a>.</li></ul><p>The <strong>Term &amp; Conditions</strong> tab holds a free text note.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><p>The buttons are in the top bar of the entry.</p><ul><li><strong>Confirm:</strong> Visible on a <strong>Draft</strong>. It posts the entry and the status becomes <strong>Posted</strong>. Aureus needs at least one line, and the accounts and journal must be active.</li><li><strong>Cancel:</strong> Visible on a <strong>Draft</strong>. The status becomes <strong>Cancelled</strong>.</li><li><strong>Reverse:</strong> Visible on a <strong>Posted</strong> entry. A window asks for <strong>Reason displayed on Reverse</strong>, <strong>Journal</strong> and <strong>Date</strong>. Aureus creates a new draft entry with debit and credit swapped and opens it. Confirm it to cancel the effect of the first.</li><li><strong>Reset To Draft:</strong> Visible on a <strong>Posted</strong> or <strong>Cancelled</strong> entry. The status goes back to <strong>Draft</strong>, so you can edit it.</li><li><strong>Delete:</strong> Removes the entry.</li></ul><p>A posted entry is read only. Reset it to draft to edit it.</p><h2 id="example-1-a-simple-entry" tabindex="-1">Example 1: a simple entry <a class="header-anchor" href="#example-1-a-simple-entry" aria-label="Permalink to &quot;Example 1: a simple entry&quot;">​</a></h2><p>Your accountant asks you to move $100.00 from the sales account to the expense account.</p><ol><li>Create an entry with <strong>Reference</strong> <code>Move 100 to expenses</code>.</li><li>Add item 1: <strong>Account</strong> <code>Expenses</code>, <strong>Debit</strong> <code>100.00</code>.</li><li>Add item 2: <strong>Account</strong> <code>Product Sales</code>, <strong>Credit</strong> <code>100.00</code>.</li><li>Click <strong>Create</strong>, then <strong>Confirm</strong>.</li></ol><p>The status is <strong>Posted</strong> and both reports now show the change.</p><h2 id="example-2-the-entry-of-an-invoice" tabindex="-1">Example 2: the entry of an invoice <a class="header-anchor" href="#example-2-the-entry-of-an-invoice" aria-label="Permalink to &quot;Example 2: the entry of an invoice&quot;">​</a></h2><p>Invoice <strong>INV/2026/1</strong> (Azure Interiors, $1,207.50) created this entry when you confirmed it.</p><table tabindex="0"><thead><tr><th>Account</th><th>Debit</th><th>Credit</th></tr></thead><tbody><tr><td>Account Receivable</td><td>1,207.50</td><td></td></tr><tr><td>Product Sales</td><td></td><td>1,050.00</td></tr><tr><td>Tax Received</td><td></td><td>157.50</td></tr></tbody></table><p>Debit and credit both total $1,207.50. On the invoice page, the <strong>Journal Items</strong> tab shows the same lines. See <a href="./../customer-invoices/create-invoice.html">Create an invoice</a>.</p><p>When Deco Addict paid invoice INV/2026/2, entry <code>PBANK/2026/3</code> debited <strong>Outstanding Receipts</strong> with $891.25 and credited <strong>Account Receivable</strong> with $891.25.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./journal-items.html">Journal items</a></li><li><a href="./">Accounting entries overview</a></li><li><a href="./../payments/register-payment.html">Register a payment</a></li><li><a href="./../get-started/journals.html">Journals</a></li></ul>',25))])}const b=r(l,[["render",c]]);export{f as __pageData,b as default};
